#include <iostream>
using namespace std;

long long fibonacci(int n) {
    if (n == 0) return 0;
    if (n == 1) return 1;

    return fibonacci(n - 1) + fibonacci(n - 2);
}

int main() {
    int n;

    cout << "Enter n: ";
    cin >> n;

    if (n < 0) {
        cout << "Please enter a non-negative number." << endl;
    } else {
        cout << "Fibonacci(" << n << ") = " << fibonacci(n) << endl;
    }

    return 0;
}
```

This program uses a simple recursive approach where:

```text
F(0) = 0
F(1) = 1
F(n) = F(n - 1) + F(n - 2)
```

Note: This recursive method is easy to understand but becomes very slow for large values of `n` because it recalculates the same Fibonacci numbers many times.
